vector<long long> ncrQueries(vector<vector<int>>& q) {
    const long long M = 1e9 + 7; int N = 1; for (auto& x : q) N = max(N, x[0]);
    auto pw = [&](long long b, long long e) { long long r = 1; b %= M; while (e) { if (e & 1) r = r * b % M; b = b * b % M; e >>= 1; } return r; };
    vector<long long> f(N + 1, 1), inv(N + 1, 1); for (int i = 1; i <= N; i++) f[i] = f[i-1] * i % M; inv[N] = pw(f[N], M - 2); for (int i = N; i > 0; i--) inv[i-1] = inv[i] * i % M;
    vector<long long> out; for (auto& x : q) { int n = x[0], r = x[1]; out.push_back(r < 0 || r > n ? 0 : f[n] * inv[r] % M * inv[n-r] % M); } return out;
}
